#include <string>

enum class Level { low, medium, high };

// The port number in the text, or -1 if it is not a valid port.
[[nodiscard]] int parsePort(const std::string& text)
{
    if (text.empty() || text.size() > 5)
    {
        return -1;
    }
    int port{ 0 };
    for (char c : text)
    {
        if (c < '0' || c > '9')
        {
            return -1;
        }
        port = port * 10 + (c - '0');
    }
    return port <= 65535 ? port : -1;
}

int onEvent(int code, [[maybe_unused]] void* context)
{
    return code * 2;
}

int priority(Level level)
{
    int value{ 0 };
    switch (level)
    {
    case Level::high:
        value += 10;
        [[fallthrough]];
    case Level::medium:
        value += 5;
        break;
    case Level::low:
        break;
    }
    return value;
}

unitTests:
TEST("parsePort") { CHECK_EQ(parsePort("8080"), 8080); CHECK_EQ(parsePort("65535"), 65535); CHECK_EQ(parsePort("65536"), -1); CHECK_EQ(parsePort("80a"), -1); CHECK_EQ(parsePort(""), -1); }
TEST("onEvent") { CHECK_EQ(onEvent(21, nullptr), 42); }
TEST("priority") { CHECK_EQ(priority(Level::high), 15); CHECK_EQ(priority(Level::medium), 5); CHECK_EQ(priority(Level::low), 0); }

